import rich.repr

class CustomEq:
    def __init__(self, value):
        self.value = value
    def __eq__(self, other):
        return True

def test_custom_eq():
    @rich.repr.auto
    class MyClass:
        def __init__(self, x, y=CustomEq(1)):
            self.x = x
            self.y = y

    obj = MyClass(10)
    # If the bug exists, param.default == param.empty will be True because CustomEq(1) == Parameter.empty is True
    # Then it will try to yield getattr(self, "y"), which is fine, but it should have yielded (name, value, default)
    # since it HAS a default.

    # Let's see what __rich_repr__ yields
    res = list(MyClass.__rich_repr__(obj))
    print(f"Result: {res}")

    # Expected: [10, ('y', <CustomEq object>, <CustomEq object>)]
    # Actual if bug: [10, <CustomEq object>]

    assert len(res) == 2
    assert isinstance(res[1], tuple)

if __name__ == "__main__":
    try:
        test_custom_eq()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")
